<script>(()=>{const list=document.getElementById('ledger-list'),grid=document.getElementById('ledger-grid'),listButton=document.getElementById('ledger-list-button'),gridButton=document.getElementById('ledger-grid-button');if(!list||!grid)return;const setView=view=>{const showGrid=view==='grid';list.hidden=showGrid;grid.hidden=!showGrid;listButton.classList.toggle('active',!showGrid);gridButton.classList.toggle('active',showGrid);listButton.setAttribute('aria-pressed',String(!showGrid));gridButton.setAttribute('aria-pressed',String(showGrid));try{localStorage.setItem('safety-shop-ledger-view',view)}catch(error){}};listButton.addEventListener('click',()=>setView('list'));gridButton.addEventListener('click',()=>setView('grid'));let saved='list';try{saved=localStorage.getItem('safety-shop-ledger-view')||'list'}catch(error){}setView(saved);})();</script>
